test('renderInvoiceText with issued invoice shows all components', () => {
  const createResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  assert.equal(createResult.ok, true);
  const issueResult = issueInvoice(createResult.value, ['INV-2025-0001']);
  assert.equal(issueResult.ok, true);

  const text = renderInvoiceText(issueResult.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2025-0002');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert(lines[2].includes('Design work (hour)'));
  assert(lines[3].includes('Development (hour)'));
  assert(lines[4].startsWith('Total:'));
});

test('renderInvoiceText output has correct line structure', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  // First line: DRAFT
  assert(lines[0] === 'DRAFT');
  // Second line: customer name
  assert(lines[1] === 'Northwind Studio');
  // Third and fourth lines: line items
  assert(lines[2].includes('Logo package'));
  assert(lines[3].includes('Brand guidelines document'));
  // Fifth line: total
  assert(lines[4].startsWith('Total:'));
  // Should be exactly 5 lines
  assert.equal(lines.length, 5);
});

test('renderInvoiceText shows discount on line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should show the discount and discounted total
  assert(text.includes('10% off'));
  assert(text.includes('-€120.00'));
  assert(text.includes('€1,080.00'));
});

test('renderInvoiceText with multiple discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
      { sku: 'BRAND-BOOK', qty: 1, discountPercent: 20 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  assert(text.includes('10% off'));
  assert(text.includes('20% off'));
  assert(text.includes('Subtotal: €3,650.00'));
  assert(text.includes('Discount: -€610.00'));
  assert(text.includes('Total: €3,040.00'));
});

test('renderInvoiceText without discounts has no discount line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  // Should not have Subtotal or Discount lines
  assert(!text.includes('Subtotal:'));
  assert(!text.includes('Discount:'));
  // Total should be the last line
  assert(lines[4].startsWith('Total:'));
});

test('renderInvoiceText decimal discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 12.5 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  assert(text.includes('12.5% off'));
});

